-- Verify OPS_G53AI
SELECT 'ops' as tbl, * FROM operations WHERE opsregistry = 'OPS_G53AI';
SELECT 'hr' as tbl, * FROM humanresources WHERE hr_ops_ref = 'OPS_G53AI';
SELECT 'ce' as tbl, safety_ranking, secincidentcount FROM coordinationandevaluation WHERE coordopsref = 'OPS_G53AI';

-- Check how many total hr records join to disasterevents
SELECT COUNT(*) FROM humanresources hr
JOIN disasterevents d ON hr.hrdistref = d.distregistry;

-- Check beneficiariesandassessments joined to operations
SELECT COUNT(*) FROM beneficiariesandassessments b
JOIN operations o ON b.beneopsref = o.opsregistry;

-- Check coordinationandevaluation joined to operations
SELECT COUNT(*) FROM coordinationandevaluation c
JOIN operations o ON c.coordopsref = o.opsregistry;

-- Check financials joined to operations
SELECT COUNT(*) FROM financials f
JOIN operations o ON f.fin_ops_ref = o.opsregistry;

-- Check transportation joined to disasterevents
SELECT COUNT(*) FROM transportation t
JOIN disasterevents d ON t.transportdistref = d.distregistry;

-- Maybe it's supplies joined with operations via hub and operation_hub_map
SELECT COUNT(*) FROM supplies s
JOIN distributionhubs d ON s.supplyhubref = d.hubregistry;

-- Let me check if there's a pattern where we get 312 by joining supplies with something
SELECT COUNT(*) FROM supplies s
JOIN disasterevents d ON s.supply_dist_ref = d.distregistry;
